    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    # The marker attached to the compact motif anchors it; the other marker
    # marks the translated anchor. The attached marker itself is not copied.
    if len(markers) != 2:
        return g
    h, w = len(grid), len(grid[0])
    # Select the marker adjacent to the densest local multicolor motif.
    scores = []
    for r, c in markers:
        score = sum(1 for rr in range(max(0,r-2), min(h,r+3))
                      for cc in range(max(0,c-2), min(w,c+3))
                      if grid[rr][cc] not in (0,5))
        scores.append(score)
    src_i = 0 if scores[0] >= scores[1] else 1
    sr, sc = markers[src_i]
    dr, dc = markers[1-src_i]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 5):
                rr, cc = r + dr - sr, c + dc - sc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                    g[rr][cc] = v
    return g
