                          for cc in range(max(0,c-3),min(w,c+4))))
    si=0 if scores[0]>=scores[1] else 1
    sr,sc=marks[si]; tr,tc=marks[1-si]
    # Translate every non-marker pattern cell relative to marker. The target
    # marker is only an anchor and is replaced by the corresponding pattern cell
    # when source pattern has one there (otherwise remains background).
    for r in range(h):
